head.script:
scwin.onpageload = function() {
console.log(WebSquare.util.isMobile());
console.log(WebSquare.util.isTouchDevice());

	var jsonData = [
    {"col1":"1","col2":"2","col3":"3"},
    {"col1":"11","col2":"12","col3":"13"}
    ];

    dataList2.setJSON(jsonData);

    var jsonData2 = [
    {"col1":"1","col2":"2","col3":"3"},
    {"col1":"11","col2":"12","col3":"13"}
    ];

    dataList2.setJSON(jsonData2);
};


	scwin.checkAriaSelectedInsideCalendar = function() {
		var calendarDiv = WebSquare.wUnit.getDomById("inputCalendar1_calendar_content");
		var returnVal = true;
		if (calendarDiv) {
			var tdElements = calendarDiv.querySelectorAll("td");
			// 선택된 각 td 요소를 순회하면서 aria-selected 속성이 있는지 확인
			tdElements.forEach(function(td) {
				if (td.hasAttribute("aria-selected")) {
					console.log("요소 내용: '" + td.textContent.trim() + "' → aria-selected 속성 값:", td.getAttribute("aria-selected"));
					returnVal = false;
				} else {
					//console.log("요소 내용: '" + td.textContent.trim() + "' → aria-selected 속성이 없습니다.");
				}
			});
		} else {
			console.log("id가 'mf_inputCalendar1_calendar_content'인 div 요소를 찾을 수 없습니다.");
		}
		return returnVal;
	}

	scwin.checkVal = function() {
	debugger;
		return scwin.checkAriaSelectedInsideCalendar();
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_img').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
